import pandas as pd
import numpy as np


def _differs(a, b):
    """Compare two values treating NaN/None as equal only to NaN/None."""
    a_na = pd.isna(a)
    b_na = pd.isna(b)
    if a_na and b_na:
        return False
    if a_na != b_na:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim = inputs['DIM_CUSTOMER'].copy()
    stg = inputs['STG_CUSTOMER'].copy()
    fact = inputs['FACT_TXN'].copy()

    # Normalize date columns
    if not dim.empty:
        dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
        dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    else:
        dim['eff_start_date'] = pd.to_datetime(dim.get('eff_start_date', pd.Series(dtype='datetime64[ns]')))
        dim['eff_end_date'] = pd.to_datetime(dim.get('eff_end_date', pd.Series(dtype='datetime64[ns]')))

    if not stg.empty:
        stg['update_date'] = pd.to_datetime(stg['update_date'])

    if not fact.empty:
        fact['txn_date'] = pd.to_datetime(fact['txn_date'])

    # Determine max existing surrogate key BEFORE the load
    if not dim.empty and dim['customer_sk'].notna().any():
        max_sk = dim['customer_sk'].max()
    else:
        max_sk = 0

    # Build a lookup of current rows per customer_id (assume at most one current row per customer)
    current_rows = dim[dim['is_current'] == 1].copy()
    current_lookup = {}
    for _, r in current_rows.iterrows():
        current_lookup[r['customer_id']] = r

    # Order staged records by customer_id for ROW_NUMBER assignment,
    # but only over records that actually create a version.
    stg_sorted = stg.sort_values('customer_id', kind='mergesort').reset_index(drop=True)

    creates = []  # list of dicts describing new version rows
    expirations = {}  # customer_sk -> end_date to expire existing current row

    for _, row in stg_sorted.iterrows():
        cid = row['customer_id']
        seg_s = row['segment']
        upd = row['update_date']

        if cid in current_lookup:
            cur = current_lookup[cid]
            if _differs(seg_s, cur['segment']):
                creates.append({
                    'customer_id': cid,
                    'segment': seg_s,
                    'eff_start_date': upd,
                })
                expirations[cur['customer_sk']] = upd
        else:
            creates.append({
                'customer_id': cid,
                'segment': seg_s,
                'eff_start_date': upd,
            })

    # Assign surrogate keys in order (row_number over creating records only)
    new_rows = []
    for i, c in enumerate(creates, start=1):
        new_sk = max_sk + i
        new_rows.append({
            'customer_sk': new_sk,
            'customer_id': c['customer_id'],
            'segment': c['segment'],
            'eff_start_date': c['eff_start_date'],
            'eff_end_date': pd.NaT,
            'is_current': 1,
        })

    # Apply expirations to the existing dim rows
    dim_out = dim.copy()
    for sk, end_date in expirations.items():
        mask = dim_out['customer_sk'] == sk
        dim_out.loc[mask, 'eff_end_date'] = end_date
        dim_out.loc[mask, 'is_current'] = 0

    if new_rows:
        new_df = pd.DataF
